// 读取传感器状态（6-bit编码）
static uint8_t read_sensor_state(void)
{
    uint8_t state = 0;
    for (int i = 0; i < HALL_MAX; i++) {
        if (hall_read(i) == true) {
            state |= (1 << i);
        }
    }
    return state;
}

// 检查是否为合法状态（单或双传感器触发）
static bool is_valid_state(uint8_t* state)
{
    switch (*state) {
        // 单传感器触发
        case 0x01:
        case 0x02:
        case 0x04:
        case 0x08:
        case 0x10:
        case 0x20:
        // 双传感器触发（相邻两个）
        case 0x03:
        case 0x06:
        case 0x0C:
        case 0x18:
        case 0x30:
        case 0x21:
            return true;
        default:
            return false; // 非法状态（如三个传感器同时触发）,无传感器触发
    }
}

// 检查方向（允许1-bit误差）
static int8_t check_direction(uint8_t* old, uint8_t* new)
{
    return global_config.dir * rules[*old][*new]; // 直接访问映射表
}

